<?php require_once __DIR__.'/../../includes/auth.php';require_login('admin');$id=(int)($_GET['id']??0);$s=$pdo->prepare('SELECT user_id FROM customers WHERE id=?');$s->execute([$id]);$uid=$s->fetchColumn();if($uid){$s=$pdo->prepare("UPDATE customers SET status='Inactive' WHERE id=?");$s->execute([$id]);$s=$pdo->prepare("UPDATE users SET status='Inactive' WHERE id=?");$s->execute([$uid]);log_activity('Customer deletion','Customer '.$id.' deactivated.');flash('success','Customer deactivated.');}redirect('admin/customers/index.php');